pub fn next_delay(attempt: u32, config: &RetryConfig) -> u64 {
    let exponent = attempt.saturating_sub(1);
    let raw = if exponent >= 64 {
        u64::MAX
    } else {
        config
            .base_delay_ms
            .checked_shl(exponent)
            .unwrap_or(u64::MAX)
    };
    config.max_delay_ms.min(raw)
}

